/* @lc app=leetcode id=2809 lang=kotlin */ class Solution { fun minimumTime(A: List<Int>, B: List<Int>, x: Int): Int = A.zip(B).sortedBy { it.second }.fold(LongArray(A.size + 1) { 0L }) { dp, (a, b) -> dp.also { (A.size downTo 1).forEach { i -> dp[i] = maxOf(dp[i], dp[i - 1] + i.toLong() * b + a) } } }.let { dp -> A.sumOf { it.toLong() }.let { sA -> B.sumOf { it.toLong() }.let { sB -> (0..A.size).firstOrNull { i -> sA + i.toLong() * sB - dp[i] <= x } ?: -1 } } } }